scenario.script:
function colonyIdToType(cid) {
    if (cid === 'c1') { return ['food', 'gold']; }
    if (cid === 'c2') { return ['soldier']; }
    if (cid === 'c3') { return ['archer']; }
    if (cid === 'c4') { return ['wood']; }
    if (cid === 'c5') { return ['gold']; }
    if (cid === 'c6') { return ['soldier', 'archer']; }
}
function colonyNeedResource(cid) {
    return ['c2', 'c3', 'c6'].includes(cid);
}

const colonySupplyTimerMax = 12;

Scenario.scriptBeginGame = () => {

//c1: central (food + gold), c2, c3: military, c4: econ (wood), c5: econ (gold), c6: military

const colonies = GameLogic.findAllWithMetadataKey("colony").map(e => ({ colonyType: colonyIdToType(e.metadata.colony), needRes: colonyNeedResource(e.metadata.colony), center: e.position, heldBy: 'None', supplyTimer: colonySupplyTimerMax }));
console.log(colonies);

//Custom AI
AI.colonyLoc = colonies.map(c => c.center);

AI.rules = [];

const customAI = () => {
const playerId = 1;
const enemyId = 0;
const radius = 40;

//Credit: https://gist.github.com/janosh/099bd8061f15e3fbfcc19be0e6b670b9
const argFact = (compareFn) => (array) => array.map((el, idx) => [el, idx]).reduce(compareFn)[1];

const argMax = argFact((min, el) => (el[0] > min[0] ? el : min));
const argMin = argFact((max, el) => (el[0] < max[0] ? el : max));

const army = state.entities.filter(e => e.owner === playerId && (e.type === CONFIG.ENTITIES.Soldier.type || e.type === CONFIG.ENTITIES.Archer.type) && !e.dead);
let armyDist = [[], [], [], [], [], []];
let outside = [];

army.forEach(e => {
    let used = false;
    AI.colonyLoc.forEach((center, idx) => {
        if (e.position.distanceTo(center) <= radius) {
            used = true;
            armyDist[idx].push(e);
        }
    });
    if (!used) {
        outside.push(e);
    }
});

const enemyarmy = state.entities.filter(e => e.owner === enemyId && (e.type === CONFIG.ENTITIES.Soldier.type || e.type === CONFIG.ENTITIES.Archer.type) && !e.dead);
const enemyarmyCount = [0,0,0,0,0,0];
enemyarmy.forEach(e => {
    AI.colonyLoc.forEach((center, idx) => {
        if (e.position.distanceTo(center) <= radius) {
            enemyarmyCount[idx] += 1;
        }
    });
});
const myCount = armyDist.map(a => a.length);
let totalCount = [0,0,0,0,0,0];

for (let i = 0; i < totalCount.length; i++) {
    totalCount[i] = enemyarmyCount[i] + myCount[i];
}

const weaknessTarget = argMin(totalCount);
const randomTarget = Math.floor(Math.random() * 5.9);
const targetCol = (Math.random() > 0.8) ? randomTarget : weaknessTarget;

let utilize = outside;
for (const colArmy of armyDist) {
    if (colArmy.length >= 3) {
        utilize = utilize.concat( colArmy.slice(3, colArmy.length) );
    }
}

moveToInFormation(utilize, AI.colonyLoc[targetCol].clone().add(new THREE.Vector3(4,0,0)) );
};

setInterval(customAI, 25 * 1000);



const colonyMesh = [];

for (const col of colonies) {

        const radius = 40;
        const height = 0.3; 
        // Use CircleGeometry for a flat look or Cylinder for volume
        // Cylinder looks better as a "zone" on the ground
        const geometry = new THREE.CylinderGeometry(radius, radius, height, 32);

        // Change color based on tool
        const color = 0x808080;

        const material = new THREE.MeshBasicMaterial({ 
            color: color, 
            transparent: false, 
            opacity: 0.5,
            side: THREE.DoubleSide
        });
        const areaMesh = new THREE.Mesh(geometry, material);

        areaMesh.position.set(col.center.x, col.center.y, col.center.z);

        scene.add(areaMesh);

        colonyMesh.push(areaMesh);

}

Scenario.scriptState = {
    colonies: colonies,
    colonyMesh: colonyMesh,
    playerId: 0,
    enemyId: 1
};

Scenario.refreshObjectivesGameUI();

state.players[0].resources.food += 300;
state.players[0].resources.wood += 200;
state.players[0].resources.gold += 100;

state.players[1].resources.food += 300;
state.players[1].resources.wood += 200;
state.players[1].resources.gold += 100;

}

Scenario.checkRes = (heldBy, colonyType) => {

let food = 0;
let wood = 0;
let gold = 0;


if (colonyType.includes('soldier') && colonyType.includes('archer')) {
    // combined army => 160, 100, 40
    food = 160; wood = 100; gold = 40;
}
else if (colonyType.includes('soldier')) {
    //infantry:60f 20g x 4 => 240,0,80
    food = 240; wood = 0; gold = 80;
} else {
    //archer: 20f 50w x 4 => 80, 200, 0
    food = 80; wood = 200; gold = 0;
}

const idx = (heldBy === 'Player') ? 0 : 1;

const existRes = state.players[idx].resources;

return (existRes.food < food) || (existRes.wood < wood) || (existRes.gold < gold);
};

Scenario.actionSupply = (heldBy, colonyType, center) => {

const north = new THREE.Vector3(0,0,4);
const east = new THREE.Vector3(4,0,0);
const south = new THREE.Vector3(0,0,-4);
const west = new THREE.Vector3(-4,0,0);

let food = 0;
let wood = 0;
let gold = 0;

let infos;

const idx = (heldBy === 'Player') ? 0 : 1;

const existRes = state.players[idx].resources;


if (colonyType.includes('food') || colonyType.includes('wood') || colonyType.includes('gold')) {

if (colonyType.includes('food') && colonyType.includes('gold')) { existRes.food += 250; existRes.gold += 150; return; }
if (colonyType.includes('wood')) { existRes.wood += 400; return; }

existRes.gold += 200; return;

}

if (colonyType.includes('soldier') && colonyType.includes('archer')) {
    // combined army => 160, 100, 40
    food = 160; wood = 100; gold = 40;
    infos = [{ type: 'Soldier', disp: north}, { type: 'Soldier', disp: east}, { type: 'Archer', disp: south}, { type: 'Archer', disp: west}];
}
else if (colonyType.includes('soldier')) {
    //infantry:60f 20g x 4 => 240,0,80
    food = 240; wood = 0; gold = 80;
    infos = [{ type: 'Soldier', disp: north}, { type: 'Soldier', disp: east}, { type: 'Soldier', disp: south}, { type: 'Soldier', disp: west}];
} else {
    //archer: 20f 50w x 4 => 80, 200, 0
    food = 80; wood = 200; gold = 0;
    infos = [{ type: 'Archer', disp: north}, { type: 'Archer', disp: east}, { type: 'Archer', disp: south}, { type: 'Archer', disp: west}];
}



existRes.food -= food;
existRes.wood -= wood;
existRes.gold -= gold;


for (const info of infos) {
    GameLogic.createUnit(info.type, idx, center.clone().add(info.disp), true);
}

};

Scenario.scriptExec = () => {
    const radius = 40;

    const cstate = Scenario.scriptState;
    if (cstate.isExecing) { return; }

//e.state === 'IDLE'
const playerArmy = state.entities.filter(e => e.owner === cstate.playerId && (e.type === CONFIG.ENTITIES.Soldier.type || e.type === CONFIG.ENTITIES.Archer.type) && !e.dead);
const enemyArmy = state.entities.filter(e => e.owner === cstate.enemyId && (e.type === CONFIG.ENTITIES.Soldier.type || e.type === CONFIG.ENTITIES.Archer.type) && !e.dead);

cstate.colonies.forEach((col, idx) => {

    const pCount = playerArmy.filter(e => e.position.distanceTo(col.center) <= radius ).length;
    const eCount = enemyArmy.filter(e => e.position.distanceTo(col.center) <= radius ).length;

    if (pCount >= 4 && eCount <= 2) {
        if (col.heldBy !== 'Player') {
            UI.showDialog("Commander", "We've occupied a colony.");
            col.heldBy = 'Player';
            col.supplyTimer = colonySupplyTimerMax + 1;
        }
    }
    if (eCount >= 4 && pCount <= 2) {
        if (col.heldBy !== 'Enemy') {
            UI.showDialog("Commander", "We've lost a colony.");
            col.heldBy = 'Enemy';
            col.supplyTimer = colonySupplyTimerMax + 1;
        }
    }

    if (col.heldBy !== 'None') {
        col.supplyTimer -= 1;
    }

    //Update visuals
    cstate.colonyMesh[idx].material.color.setHex( (col.heldBy === 'Enemy') ? 0xff0000 : ( (col.heldBy === 'Player') ? 0x0000ff : 0x808080 ));

    //Supply
    if (col.supplyTimer <= 0) {
        let queueBlocked = false;
        if (col.needRes) {
            queueBlocked = Scenario.checkRes(col.heldBy, col.colonyType);
        }
        if (!queueBlocked) {

            Scenario.actionSupply(col.heldBy, col.colonyType, col.center);

            UI.notify("Colony supply arrived");
            col.supplyTimer = colonySupplyTimerMax;
        } else {
            UI.notify("Colony production blocked due to insufficient resources.");
        }
    }

});

Scenario.objectives.additionalNotes = `Controled: ${cstate.colonies.filter(c => c.heldBy === 'Player').length}/6 colonies.`;
Scenario.refreshObjectivesGameUI();


state.entities.filter(e => e.owner === cstate.playerId && (e.type === CONFIG.ENTITIES.Soldier.type || e.type === CONFIG.ENTITIES.Archer.type) && !e.dead && e.targetEntity).forEach(e => {

    e.targetEntity.state = 'IDLE';

})

};
